import React, { useMemo } from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";
import { smoothClosedPath, type Pt } from "../utils/geometry";

const scallop = (r: number, bumps: number, depth: number): string => {
  const pts: Pt[] = [];
  for (let i = 0; i < bumps * 2; i++) {
    const a = (i / (bumps * 2)) * Math.PI * 2;
    const rr = i % 2 === 0 ? r : r * (1 - depth);
    pts.push([Math.cos(a) * rr, Math.sin(a) * rr]);
  }
  return smoothClosedPath(pts);
};

const OUTER = scallop(10, 14, 0.13);
const MID = scallop(7.6, 12, 0.15);
const INNER = scallop(4.8, 9, 0.2);

const TONES = {
  orange: { outer: "#DE7A18", mid: "#EE9A2C", inner: "#F7B947", heart: "#A9500F" },
  yellow: { outer: "#E2A826", mid: "#F0C241", inner: "#F9D96A", heart: "#A87A14" },
  rose: { outer: "#A8374A", mid: "#C4526A", inner: "#D8788A", heart: "#6E1A2A" },
  ivory: { outer: "#EFE3C8", mid: "#F7EEDB", inner: "#FFF9EC", heart: "#C9A55A" },
} as const;
export type FlowerTone = keyof typeof TONES;

/** Stylised marigold (or rose/jasmine tone): three ruffled rings and a heart. */
export const Flower: React.FC<{ x: number; y: number; r: number; tone?: FlowerTone; rot?: number }> = ({
  x,
  y,
  r,
  tone = "orange",
  rot = 0,
}) => {
  const t = TONES[tone];
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${r / 10})`}>
      <path d={OUTER} fill={t.outer} />
      <path d={MID} fill={t.mid} />
      <path d={INNER} fill={t.inner} />
      <circle r={1.7} fill={t.heart} />
    </g>
  );
};

const LEAF = "M0 0 C5 -6 15 -6 20 0 C15 6 5 6 0 0 Z";
export const Leaf: React.FC<{ x: number; y: number; rot: number; s?: number; color?: string }> = ({
  x,
  y,
  rot,
  s = 1,
  color = palette.green,
}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${s})`}>
    <path d={LEAF} fill={color} />
    <path d="M1 0 L18 0" stroke={palette.greenDeep} strokeWidth={0.8} opacity={0.6} />
  </g>
);

/** A vertical string of marigolds (ladi) ending in a rose and a gold bead. */
export const MarigoldStrand: React.FC<{ x: number; y: number; length: number; r?: number; seed?: string; sway?: number }> = ({
  x,
  y,
  length,
  r = 9,
  seed = "strand",
  sway = 0,
}) => {
  const n = Math.floor(length / (r * 1.75));
  return (
    <g>
      <path d={`M${x} ${y} Q${x + sway * 0.5} ${y + length / 2} ${x + sway} ${y + length}`} stroke={palette.goldDeep} strokeWidth={1} fill="none" />
      {new Array(n).fill(0).map((_, i) => {
        const t = i / Math.max(1, n - 1);
        const fx = x + sway * t * t + (random(`${seed}-${i}`) - 0.5) * 1.5;
        const fy = y + r + i * r * 1.75;
        const tone: FlowerTone = i % 3 === 2 ? "yellow" : "orange";
        return <Flower key={i} x={fx} y={fy} r={r} tone={tone} rot={random(`${seed}-r${i}`) * 90} />;
      })}
      <Flower x={x + sway} y={y + r + n * r * 1.75 + 2} r={r * 0.95} tone="rose" />
      <circle cx={x + sway} cy={y + r + n * r * 1.75 + r + 8} r={3} fill="url(#foil)" />
    </g>
  );
};

/** Marigold garland hung between two points with a natural sag, leaves tucked in. */
export const GarlandSwag: React.FC<{ from: Pt; to: Pt; sag: number; r?: number; seed?: string; tones?: FlowerTone[] }> = ({
  from,
  to,
  sag,
  r = 10,
  seed = "swag",
  tones = ["orange", "orange", "yellow"],
}) => {
  const flowers = useMemo(() => {
    const [x0, y0] = from;
    const [x1, y1] = to;
    const cx = (x0 + x1) / 2;
    const cy = (y0 + y1) / 2 + sag * 2;
    const len = Math.hypot(x1 - x0, y1 - y0) + sag;
    const n = Math.max(2, Math.floor(len / (r * 1.6)));
    return new Array(n + 1).fill(0).map((_, i) => {
      const t = i / n;
      const u = 1 - t;
      return {
        x: u * u * x0 + 2 * u * t * cx + t * t * x1,
        y: u * u * y0 + 2 * u * t * cy + t * t * y1,
        tone: tones[i % tones.length],
        rot: random(`${seed}-${i}`) * 90,
        leaf: i % 4 === 1,
        leafRot: random(`${seed}-l${i}`) * 360,
      };
    });
  }, [from, to, sag, r, seed, tones]);
  return (
    <g>
      {flowers.map((f, i) =>
        f.leaf ? <Leaf key={`l${i}`} x={f.x} y={f.y} rot={f.leafRot} s={r / 9} /> : null,
      )}
      {flowers.map((f, i) => (
        <Flower key={i} x={f.x} y={f.y} r={r} tone={f.tone} rot={f.rot} />
      ))}
    </g>
  );
};

/** Loose rose/marigold petal. */
export const Petal: React.FC<{ x: number; y: number; rot: number; s?: number; color?: string }> = ({
  x,
  y,
  rot,
  s = 1,
  color = palette.rose,
}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${s})`}>
    <path d="M0 0 C6 -8 16 -8 18 0 C16 7 6 8 0 0 Z" fill={color} />
    <path d="M3 0 C8 -2 12 -2 15 0" stroke="#FFFFFF" strokeWidth={0.8} opacity={0.25} fill="none" />
  </g>
);
